extends Node3D
class_name TunisSchoolZonePass

var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_school_crossing()
    _build_school_signs()
    _build_guard_rails()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    for node in medium_detail_nodes:
        if is_instance_valid(node): node.visible = current_detail_level >= 1
    for node in high_detail_nodes:
        if is_instance_valid(node): node.visible = current_detail_level >= 2

func _register(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2: high_detail_nodes.append(node)
    elif minimum_level == 1: medium_detail_nodes.append(node)
    return node

func _mat(color: Color) -> StandardMaterial3D:
    var m := StandardMaterial3D.new(); m.albedo_color = color; m.roughness = 0.82; return m

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var n := MeshInstance3D.new(); var mesh := BoxMesh.new(); mesh.size = size
    n.mesh = mesh; n.position = pos; n.material_override = _mat(color); parent.add_child(n); return n

func _label(parent: Node3D, text: String, pos: Vector3) -> Label3D:
    var l := Label3D.new(); l.text = text; l.position = pos; l.font_size = 42; l.pixel_size = 0.0075
    l.outline_size = 6; l.billboard = BaseMaterial3D.BILLBOARD_ENABLED; parent.add_child(l); return l

func _build_school_crossing() -> void:
    var root := Node3D.new(); root.name = "SchoolCrossing"; add_child(root)
    for x in range(-5, 6, 2):
        _box(root, Vector3(float(x),0.095,-60.0), Vector3(0.8,0.03,10.5), Color("#ece7d5"))

func _build_school_signs() -> void:
    var root := Node3D.new(); root.name = "SchoolZoneSigns"; add_child(root); _register(root,1)
    for p in [Vector3(-9.5,2.2,-52.0), Vector3(9.5,2.2,-68.0)]:
        _box(root,p,Vector3(0.18,4.0,0.18),Color("#777777"))
        _box(root,p+Vector3(0,1.75,0),Vector3(2.8,1.5,0.16),Color("#f0d44f"))
        _label(root,"مدرسة / ÉCOLE",p+Vector3(0,1.75,0.1))

func _build_guard_rails() -> void:
    var root := Node3D.new(); root.name = "SchoolGuardRails"; add_child(root); _register(root,2)
    for z in [-50.0,-46.0,-42.0,42.0,46.0,50.0]:
        _box(root,Vector3(-8.7,0.75,z),Vector3(0.12,1.3,3.0),Color("#d9d9d0"))

extends Node3D
class_name TunisStreetArtPass

const PROFILE_PATH := "res://data/art/tunis_art_profile.json"

var profile: Dictionary = {}
var generated_prop_count := 0

func _ready() -> void:
    _load_profile()

func build(using_real_osm: bool) -> void:
    if profile.is_empty():
        _load_profile()

    _build_lane_markings()
    _build_curbs()
    _build_bollards()
    _build_street_furniture()
    _build_rooftop_silhouette_props(using_real_osm)
    _build_local_commerce_cluster()
    _build_local_labels()

func _load_profile() -> void:
    if not FileAccess.file_exists(PROFILE_PATH):
        return
    var f := FileAccess.open(PROFILE_PATH, FileAccess.READ)
    if f == null:
        return
    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) == TYPE_DICTIONARY:
        profile = parsed

func _color(key: String, fallback: String) -> Color:
    var palette = profile.get("palette", {})
    if typeof(palette) != TYPE_DICTIONARY:
        return Color(fallback)
    return Color(str(palette.get(key, fallback)))

func _material(color: Color, roughness := 0.82, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(parent: Node, position: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = position
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_prop_count += 1
    return instance

func _cylinder(parent: Node, position: Vector3, radius: float, height: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := CylinderMesh.new()
    mesh.top_radius = radius
    mesh.bottom_radius = radius
    mesh.height = height
    instance.mesh = mesh
    instance.position = position
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_prop_count += 1
    return instance

func _build_lane_markings() -> void:
    var white := Color("#e6e2d4")
    var yellow := Color("#d4af37")

    for i in range(-5, 6):
        var x := float(i) * 18.0
        _box(self, Vector3(x, 0.12, -0.05), Vector3(8.0, 0.035, 0.16), white)
        _box(self, Vector3(-0.05, 0.13, x), Vector3(0.16, 0.035, 8.0), white)

    for i in range(-5, 6, 2):
        var x := float(i) * 18.0
        _box(self, Vector3(x, 0.125, 60.0), Vector3(7.0, 0.035, 0.12), yellow)

func _build_curbs() -> void:
    var curb := _color("curb", "#d7d3c7")
    var curb_positions = [-67.5, -52.5, -7.5, 7.5, 52.5, 67.5]

    for z in curb_positions:
        _box(self, Vector3(0, 0.19, z), Vector3(220, 0.26, 0.38), curb)

    for x in curb_positions:
        _box(self, Vector3(x, 0.20, 0), Vector3(0.38, 0.26, 220), curb)

func _build_bollards() -> void:
    var dark := Color("#383a3c")
    var positions = [
        Vector3(-12,0,12), Vector3(-8,0,12), Vector3(-4,0,12),
        Vector3(4,0,12), Vector3(8,0,12), Vector3(12,0,12),
        Vector3(-12,0,-12), Vector3(-8,0,-12), Vector3(-4,0,-12),
        Vector3(4,0,-12), Vector3(8,0,-12), Vector3(12,0,-12)
    ]
    for pos in positions:
        _cylinder(self, pos + Vector3(0,0.45,0), 0.10, 0.9, dark)

func _build_street_furniture() -> void:
    var metal := Color("#41484c")
    var wood := Color("#6d513d")

    for i in range(5):
        var z := -22.0 + float(i) * 11.0
        _box(self, Vector3(-10.5, 0.65, z), Vector3(2.6, 0.16, 0.55), wood)
        _box(self, Vector3(-11.45, 0.36, z), Vector3(0.13, 0.72, 0.13), metal)
        _box(self, Vector3(-9.55, 0.36, z), Vector3(0.13, 0.72, 0.13), metal)

func _build_rooftop_silhouette_props(using_real_osm: bool) -> void:
    if using_real_osm:
        return

    var tank := _color("tank_black", "#282b2f")
    var ac := Color("#c9c9c3")
    var dish := Color("#b7b9bb")

    var rooftops = [
        Vector3(-85,13,-85), Vector3(-30,16,-85), Vector3(30,12,-85), Vector3(85,17,-85),
        Vector3(-85,15,-30), Vector3(30,14,-30), Vector3(85,16,-30),
        Vector3(-30,13,30), Vector3(30,17,30), Vector3(85,15,30),
        Vector3(-85,14,85), Vector3(30,16,85)
    ]

    for i in range(rooftops.size()):
        var base: Vector3 = rooftops[i]
        _cylinder(self, base + Vector3(2.0,0.65,0), 0.68, 1.3, tank)
        _box(self, base + Vector3(-2.0,0.45,0), Vector3(1.4,0.9,0.55), ac)

        var pole := _cylinder(self, base + Vector3(0,0.55,2.0), 0.04, 1.1, Color("#55585a"))
        pole.rotation_degrees.z = 12.0

        var dish_mesh := MeshInstance3D.new()
        var sphere := SphereMesh.new()
        sphere.radius = 0.55
        sphere.height = 0.18
        dish_mesh.mesh = sphere
        dish_mesh.position = base + Vector3(0,1.12,2.0)
        dish_mesh.scale = Vector3(1.0,0.32,1.0)
        dish_mesh.rotation_degrees = Vector3(62, 0, 0)
        dish_mesh.material_override = _material(dish, 0.62, 0.15)
        add_child(dish_mesh)
        generated_prop_count += 1

func _build_local_commerce_cluster() -> void:
    var awning_red := _color("awning_red", "#a83f36")
    var awning_cream := _color("awning_cream", "#e7d5ad")
    var crate_blue := Color("#2d74a2")
    var bottle := Color("#7ac8d1")

    # Cafe awning + tables
    _box(self, Vector3(-46,3.5,-69.2), Vector3(10,0.20,2.7), awning_red)
    for i in range(4):
        var x := -49.0 + float(i) * 2.0
        _cylinder(self, Vector3(x,0.55,-65.8), 0.48, 0.08, awning_cream)
        _cylinder(self, Vector3(x,0.28,-65.8), 0.05, 0.55, Color("#373737"))

    _build_water_crates(crate_blue, bottle)

    # Garage canopy and oil barrels
    _box(self, Vector3(-30,3.2,54.0), Vector3(11,0.20,4.0), _color("awning_cream", "#e7d5ad"))
    for i in range(3):
        _cylinder(self, Vector3(-34.0 + i * 1.4,0.6,51.8), 0.42, 1.2, Color("#5f6d74"))

func _build_water_crates(crate_blue: Color, bottle: Color) -> void:
    for row in range(2):
        for col in range(5):
            var crate_position := Vector3(25.0 + col * 0.9, 0.45 + row * 0.72, -64.8)
            _box(self, crate_position, Vector3(0.75,0.62,0.55), crate_blue)
            for bottle_index in range(3):
                _cylinder(
                    self,
                    crate_position + Vector3(-0.22 + bottle_index * 0.22, 0.47, 0.0),
                    0.06,
                    0.50,
                    bottle
                )

func _build_local_labels() -> void:
    var labels = profile.get("street_labels", [])
    if typeof(labels) != TYPE_ARRAY:
        return

    for entry in labels:
        if typeof(entry) != TYPE_DICTIONARY:
            continue
        var p = entry.get("position", [0,0,0])
        if typeof(p) != TYPE_ARRAY or p.size() < 3:
            continue

        var sign := _box(
            self,
            Vector3(float(p[0]), float(p[1]), float(p[2])),
            Vector3(6.4,1.25,0.18),
            Color("#1f2426")
        )

        var label := Label3D.new()
        label.text = str(entry.get("text",""))
        label.font_size = 44
        label.pixel_size = 0.008
        label.outline_size = 7
        label.position = sign.position + Vector3(0,0,0.14)
        label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
        add_child(label)
        generated_prop_count += 1

extends Node3D
class_name TunisStreetDetailPass

var generated_count := 0

func build() -> void:
    _crosswalk(Vector3(0,0.12,-18), true)
    _crosswalk(Vector3(18,0.12,0), false)
    _asphalt_repairs()
    _louage_stop()
    _cafe_chairs()
    _direction_signs()

func _crosswalk(center: Vector3, horizontal: bool) -> void:
    for i in range(-4,5):
        var offset := float(i) * 0.95
        var size := Vector3(0.62,0.035,5.6) if horizontal else Vector3(5.6,0.035,0.62)
        var pos := center + (Vector3(offset,0,0) if horizontal else Vector3(0,0,offset))
        _box(pos,size,Color("#dedbd1"))

func _asphalt_repairs() -> void:
    var patches = [
        {"p":Vector3(-25,0.115,0), "s":Vector3(12,0.02,4)},
        {"p":Vector3(44,0.115,60), "s":Vector3(9,0.02,3)},
        {"p":Vector3(0,0.115,-43), "s":Vector3(4,0.02,10)}
    ]
    for entry in patches:
        var patch := _box(entry["p"],entry["s"],Color("#242628"))
        patch.rotation_degrees.y = 4.0

func _louage_stop() -> void:
    _box(Vector3(42,1.55,51.5),Vector3(6.8,3.0,0.18),Color("#d9d5c8"))
    _box(Vector3(42,3.15,51.0),Vector3(7.4,0.18,1.15),Color("#9e3132"))
    _label(Vector3(42,2.05,51.36),"LOUAGE\nتونس",0.009)
    for x in [39.8,42.0,44.2]:
        _box(Vector3(x,0.62,49.9),Vector3(1.7,0.12,0.55),Color("#5e4939"))

func _cafe_chairs() -> void:
    for row in range(2):
        for col in range(5):
            var p := Vector3(-50.0 + col * 1.65,0.42,-64.5 + row * 1.7)
            _chair(p)

func _chair(pos: Vector3) -> void:
    var metal := Color("#34383a")
    _box(pos,Vector3(0.55,0.08,0.55),metal)
    _box(pos+Vector3(0,0.55,0.24),Vector3(0.55,0.72,0.07),metal)
    for x in [-0.23,0.23]:
        for z in [-0.23,0.23]:
            _box(pos+Vector3(x,-0.28,z),Vector3(0.06,0.62,0.06),metal)

func _direction_signs() -> void:
    var pole_color := Color("#3a3d3f")
    _box(Vector3(9.8,2.3,-8.8),Vector3(0.12,4.6,0.12),pole_color)
    _sign(Vector3(9.8,4.1,-8.8),"شارع الحبيب بورقيبة",Color("#315a79"))
    _sign(Vector3(9.8,3.45,-8.8),"المدينة العتيقة",Color("#315a79"))
    _sign(Vector3(9.8,2.8,-8.8),"باب البحر",Color("#315a79"))

func _sign(pos: Vector3, text: String, color: Color) -> void:
    _box(pos,Vector3(5.1,0.48,0.13),color)
    _label(pos+Vector3(0,0,-0.09),text,0.006)

func _label(pos: Vector3, text: String, pixel: float) -> void:
    var label := Label3D.new()
    label.position = pos
    label.text = text
    label.font_size = 48
    label.pixel_size = pixel
    label.outline_size = 6
    label.billboard = BaseMaterial3D.BILLBOARD_ENABLED
    add_child(label)

func _box(pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var mi := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    mi.mesh = mesh
    mi.position = pos
    var mat := StandardMaterial3D.new()
    mat.albedo_color = color
    mat.roughness = 0.82
    mi.material_override = mat
    add_child(mi)
    generated_count += 1
    return mi
